=item * C<< $msg->backup_appliance_locks() >> / C<< $msg->backup_appliance_locks($value) >>

Type: C<Message> (L<Google::Cloud::Backupdr::V1::Backupvault::BackupLock>)

Optional. The list of BackupLocks taken by the accessor Backup Appliance.

=item * C<< $msg->compute_instance_backup_properties() >> / C<< $msg->compute_instance_backup_properties($value) >>

Type: C<Message> (L<Google::Cloud::Backupdr::V1::BackupvaultGce::ComputeInstanceBackupProperties>)

Output only. Compute Engine specific backup properties.

=item * C<< $msg->cloud_sql_instance_backup_properties() >> / C<< $msg->cloud_sql_instance_backup_properties($value) >>

Type: C<Message> (L<Google::Cloud::Backupdr::V1::BackupvaultCloudsql::CloudSqlInstanceBackupProperties>)

Output only. Cloud SQL specific backup properties.

=item * C<< $msg->backup_appliance_backup_properties() >> / C<< $msg->backup_appliance_backup_properties($value) >>

Type: C<Message> (L<Google::Cloud::Backupdr::V1::BackupvaultBa::BackupApplianceBackupProperties>)

Output only. Backup Appliance specific backup properties.

=item * C<< $msg->alloy_db_backup_properties() >> / C<< $msg->alloy_db_backup_properties($value) >>

Type: C<Message> (L<Google::Cloud::Backupdr::V1::BackupvaultAlloydb::AlloyDbClusterBackupProperties>)

Output only. AlloyDB specific backup properties.

=item * C<< $msg->disk_backup_properties() >> / C<< $msg->disk_backup_properties($value) >>

Type: C<Message> (L<Google::Cloud::Backupdr::V1::BackupvaultDisk::DiskBackupProperties>)

