=item * C<< $msg->backup_type() >> / C<< $msg->backup_type($value) >>

Type: C<Enum> (L<Google::Cloud::Backupdr::V1::Backup::BackupType>)

Output only. Type of the backup, unspecified, scheduled or ondemand.

=item * C<< $msg->gcp_backup_plan_info() >> / C<< $msg->gcp_backup_plan_info($value) >>

Type: C<Message> (L<Google::Cloud::Backupdr::V1::Backupvault::Backup::GCPBackupPlanInfo>)

Output only. Configuration for a Google Cloud resource.

